package web

import (
	"crypto/sha256"
	"encoding/hex"
	"fmt"
	"sort"
	"strings"
)

// The files the agent writes say so on their first line, and say that edits
// are replaced: the panel's state is the source of truth.
const banner = "Generated by LPanel. Changes made here are replaced the next time the account's sites change."

// renderInclude is /etc/httpd/conf.d/lpanel.conf, the one file the agent
// adds to Apache's own configuration. It defines the log format, a default
// site for names nobody serves, and includes every account's file.
//
// The sites folder is a variable, so a candidate can be tested whole without
// touching the live one: httpd -t -C "Define LPANEL_SITES <stage>".
func renderInclude(sites string) []byte {
	var b strings.Builder
	b.WriteString("# " + banner + "\n\n")
	// %O and %I are bytes sent and received (mod_logio), for bandwidth.
	b.WriteString(`LogFormat "%v %h %l %u %t \"%r\" %>s %O %I \"%{Referer}i\" \"%{User-Agent}i\"" lpanel` + "\n\n")
	b.WriteString("<IfDefine !LPANEL_SITES>\n    Define LPANEL_SITES " + sites + "\n</IfDefine>\n\n")
	b.WriteString("# The first site on *:80 answers names that no account serves: a 404,\n")
	b.WriteString("# never some customer's site.\n")
	b.WriteString("<VirtualHost *:80>\n")
	b.WriteString("    ServerName lpanel-default.invalid\n")
	b.WriteString("    RewriteEngine On\n")
	b.WriteString("    RewriteRule ^ - [R=404,L]\n")
	b.WriteString("</VirtualHost>\n\n")
	b.WriteString("IncludeOptional ${LPANEL_SITES}/*.conf\n")
	return []byte(b.String())
}

// renderSites is one account's Apache file: a VirtualHost per site.
// It returns the content and its revision, a hash of everything else in it.
// Each site sends the revision in a header, which is how the probe knows
// Apache serves this version and not the one before.
func (m *Manager) renderSites(a ApplyArgs, home string) ([]byte, string) {
	var b strings.Builder
	for i, s := range a.Sites {
		if i > 0 {
			b.WriteString("\n")
		}
		b.WriteString("<VirtualHost *:80>\n")
		fmt.Fprintf(&b, "    ServerName %s\n", s.Name)
		if len(s.Aliases) > 0 {
			fmt.Fprintf(&b, "    ServerAlias %s\n", strings.Join(s.Aliases, " "))
		}
		b.WriteString("    Header always set X-LPanel-Revision \"@REVISION@\"\n")
		fmt.Fprintf(&b, "    CustomLog \"%s/%s.access.log\" lpanel\n", m.LogDir, a.Username)
		fmt.Fprintf(&b, "    ErrorLog \"%s/%s.error.log\"\n", m.LogDir, a.Username)
		if a.Suspended {
			b.WriteString("    RewriteEngine On\n")
			b.WriteString("    RewriteRule ^ - [R=503,L]\n")
			b.WriteString("    ErrorDocument 503 \"This site is suspended.\"\n")
			b.WriteString("</VirtualHost>\n")
			continue
		}
		root := home + "/" + s.Docroot
		fmt.Fprintf(&b, "    DocumentRoot \"%s\"\n", root)
		fmt.Fprintf(&b, "    <Directory \"%s\">\n", root)
		b.WriteString("        Options -Indexes +SymLinksIfOwnerMatch\n")
		// .htaccess works, but cannot turn on following any link or
		// running CGI: only what is listed.
		b.WriteString("        AllowOverride AuthConfig FileInfo Indexes Limit Options=Indexes,MultiViews,SymLinksIfOwnerMatch\n")
		b.WriteString("        Require all granted\n")
		b.WriteString("        DirectoryIndex index.php index.html index.htm\n")
		b.WriteString("    </Directory>\n")
		b.WriteString("    <FilesMatch \"\\.php$\">\n")
		fmt.Fprintf(&b, "        SetHandler \"proxy:unix:%s|fcgi://lpanel-%s-%s\"\n", m.socket(s.PHP, a.Username), a.Username, s.PHP)
		b.WriteString("    </FilesMatch>\n")
		b.WriteString("</VirtualHost>\n")
	}
	body := b.String()
	sum := sha256.Sum256([]byte(body))
	rev := hex.EncodeToString(sum[:])[:16]
	head := fmt.Sprintf("# %s\n# Account %s, revision %s.\n\n", banner, a.Username, rev)
	return []byte(head + strings.ReplaceAll(body, "@REVISION@", rev)), rev
}

// renderPool is the account's PHP-FPM pool for one PHP version. It runs as
// the account's own user; only Apache (the web group) may use its socket.
func (m *Manager) renderPool(a ApplyArgs, home, version string) []byte {
	var b strings.Builder
	fmt.Fprintf(&b, "; %s\n; Account %s, PHP %s.%s.\n\n", banner, a.Username, version[:1], version[1:])
	fmt.Fprintf(&b, "[lpanel-%s]\n", a.Username)
	fmt.Fprintf(&b, "user = %s\ngroup = %s\n", a.Username, a.Username)
	fmt.Fprintf(&b, "listen = %s\n", m.socket(version, a.Username))
	fmt.Fprintf(&b, "listen.owner = %s\nlisten.group = %s\nlisten.mode = 0660\n", a.Username, m.WebGroup)
	b.WriteString("pm = ondemand\n")
	fmt.Fprintf(&b, "pm.max_children = %d\n", a.Pool.MaxChildren)
	b.WriteString("pm.process_idle_timeout = 30s\npm.max_requests = 500\n")
	fmt.Fprintf(&b, "chdir = %s\n", home)
	b.WriteString("security.limit_extensions = .php\n")
	// Sessions, uploads and temporary files stay in the account's own
	// folder: Remi's shared session folder is not writable by the account,
	// and a shared one would let accounts read each other's sessions.
	for _, k := range []string{"session.save_path", "upload_tmp_dir", "sys_temp_dir"} {
		fmt.Fprintf(&b, "php_admin_value[%s] = %s/tmp\n", k, home)
	}
	fmt.Fprintf(&b, "php_admin_value[error_log] = %s/logs/php-error.log\n", home)
	b.WriteString("php_admin_flag[log_errors] = on\n")
	return []byte(b.String())
}

// versions are the PHP versions an account's sites use, sorted.
func versions(a ApplyArgs) []string {
	seen := map[string]bool{}
	var out []string
	for _, s := range a.Sites {
		if !seen[s.PHP] {
			seen[s.PHP] = true
			out = append(out, s.PHP)
		}
	}
	sort.Strings(out)
	return out
}
